#!/usr/bin/env python3
"""
OpenCode Zen Free Tier Gateway v19
Правильная конвертация content для assistant/user сообщений
"""

import json
import secrets
import uuid
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.request import Request, urlopen
from urllib.error import HTTPError, URLError
from datetime import datetime

LISTEN_PORT = 9877
CHAT_URL = "https://opencode.ai/zen/v1/chat/completions"
RESPONSES_URL = "https://opencode.ai/zen/v1/responses"

MUSE_MODELS = {"muse-spark-1.3", "muse-spark-1.3-contributor-free", "muse-spark-1.2", "muse-spark-1.2-contributor-free"}
API_KEY = "oc_sk_07f344ca7fd8_-DEFG-uGh-p7fNNzOFFV7IElODLux_SS"

def generate_session_id():
    part1 = secrets.token_hex(6)
    part2 = ''.join(secrets.choice('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz') for _ in range(14))
    return f"ses_{part1}{part2}"

SESSION_ID = generate_session_id()
REQUEST_COUNTER = 0

def get_next_request_id():
    global REQUEST_COUNTER
    REQUEST_COUNTER += 1
    return f"req_{secrets.token_hex(16)}"

def is_muse_model(model):
    return model and any(muse in model.lower() for muse in MUSE_MODELS)

def get_cli_headers():
    return {
        "User-Agent": "opencode/1.18.32 (linux; x64)",
        "x-opencode-client": "cli",
        "x-opencode-version": "1.18.32",
        "x-opencode-session": SESSION_ID,
        "x-opencode-request": get_next_request_id(),
        "x-opencode-project": "default",
        "x-opencode-mode": "agent",
        "HTTP-Referer": "https://opencode.ai/",
        "X-Title": "opencode",
        "Authorization": f"Bearer {API_KEY}",
    }

def get_default_tools(for_responses):
    t1 = {"type": "function", "name": "shell", "description": "Execute shell commands", "parameters": {"type": "object", "properties": {"command": {"type": "string"}}, "required": ["command"]}}
    t2 = {"type": "function", "name": "read", "description": "Read file contents", "parameters": {"type": "object", "properties": {"path": {"type": "string"}}, "required": ["path"]}}
    if for_responses:
        return [t1, t2]
    else:
        f1 = {"name": "shell", "description": "Execute shell commands", "parameters": {"type": "object", "properties": {"command": {"type": "string"}}, "required": ["command"]}}
        f2 = {"name": "read", "description": "Read file contents", "parameters": {"type": "object", "properties": {"path": {"type": "string"}}, "required": ["path"]}}
        return [{"type": "function", "function": f1}, {"type": "function", "function": f2}]

def transform_tools(tools, for_responses):
    result = []
    for tool in (tools or []):
        if not tool or not isinstance(tool, dict):
            continue
        if for_responses and "name" in tool and "function" not in tool:
            result.append(tool)
        elif "function" in tool:
            func = tool.get("function", {})
            if for_responses:
                result.append({"type": "function", "name": func.get("name", "unknown"), "description": func.get("description", ""), "parameters": func.get("parameters", {"type": "object", "properties": {}})})
            else:
                result.append(tool)
        elif "name" in tool:
            result.append({"type": tool.get("type", "function"), "name": tool.get("name"), "description": tool.get("description", ""), "parameters": tool.get("parameters", {"type": "object", "properties": {}})})
    return result if result else get_default_tools(for_responses)

def convert_user_content(content):
    """Конвертирует user content в Responses API format (input_text, input_image)"""
    if isinstance(content, str):
        return [{"type": "input_text", "text": content}]
    elif isinstance(content, list):
        result = []
        for part in content:
            if isinstance(part, str):
                result.append({"type": "input_text", "text": part})
            elif isinstance(part, dict):
                ptype = part.get("type")
                if ptype == "text":
                    result.append({"type": "input_text", "text": part.get("text", "")})
                elif ptype == "image_url":
                    img_url = part.get("image_url", {})
                    url = img_url.get("url", "") if isinstance(img_url, dict) else str(img_url)
                    result.append({"type": "input_image", "image_url": url})
                elif ptype == "image":
                    result.append({"type": "input_image", "image_url": part.get("image_url", {}).get("url", "")})
                elif ptype == "file":
                    file_data = part.get("file", {})
                    if isinstance(file_data, dict):
                        file_name = file_data.get("filename", "file")
                        file_content = file_data.get("file_data", "")
                        result.append({"type": "input_text", "text": f"[File: {file_name}]"})
                    else:
                        result.append({"type": "input_text", "text": str(file_data)})
                elif ptype == "input_text":
                    result.append(part)
                elif ptype == "input_image":
                    result.append(part)
        return result if result else [{"type": "input_text", "text": ""}]
    else:
        return [{"type": "input_text", "text": str(content)}]

def convert_assistant_content(content):
    """Конвертирует assistant content в Responses API format (output_text)"""
    if isinstance(content, str):
        return [{"type": "output_text", "text": content}]
    elif isinstance(content, list):
        result = []
        for part in content:
            if isinstance(part, str):
                result.append({"type": "output_text", "text": part})
            elif isinstance(part, dict):
                ptype = part.get("type")
                if ptype == "text":
                    result.append({"type": "output_text", "text": part.get("text", "")})
                elif ptype == "output_text":
                    result.append(part)
        return result if result else [{"type": "output_text", "text": ""}]
    else:
        return [{"type": "output_text", "text": str(content)}]

class ZenProxyHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        print(f"[{datetime.now().strftime('%H:%M:%S')}] {args[0]}")

    def do_POST(self):
        if self.path in ['/v1/chat/completions', '/chat/completions', '/v1/responses', '/responses']:
            self.handle_unified()
        else:
            self.send_error(404)

    def handle_unified(self):
        try:
            content_length = int(self.headers.get('Content-Length', 0))
            body = self.rfile.read(content_length)
            data = json.loads(body) if body else {}
            model = data.get("model", "big-pickle")
            use_responses = is_muse_model(model)
            upstream_url = RESPONSES_URL if use_responses else CHAT_URL
            client_wants_stream = data.get("stream", False)
            data["stream"] = True
            if "tools" in data:
                data["tools"] = transform_tools(data["tools"], use_responses)
            else:
                data["tools"] = get_default_tools(use_responses)
            if use_responses:
                if "messages" in data:
                    messages = data.pop("messages")
                    input_items = []
                    for msg in messages:
                        role = msg.get("role")
                        content = msg.get("content", "")
                        if role == "user":
                            parts = convert_user_content(content)
                            input_items.append({"type": "message", "role": "user", "content": parts})
                        elif role == "assistant":
                            if msg.get("tool_calls"):
                                for tc in msg["tool_calls"]:
                                    fn = tc.get("function", {})
                                    input_items.append({"type": "function_call", "call_id": tc.get("id"), "name": fn.get("name"), "arguments": fn.get("arguments", "")})
                            if content:
                                parts = convert_assistant_content(content)
                                input_items.append({"type": "message", "role": "assistant", "content": parts})
                        elif role == "tool":
                            input_items.append({"type": "function_call_output", "call_id": msg.get("tool_call_id"), "output": content if isinstance(content, str) else json.dumps(content)})
                    data["input"] = input_items
                if "max_tokens" in data:
                    data["max_output_tokens"] = data.pop("max_tokens")
            else:
                if data.get("stream"):
                    data["stream_options"] = {"include_usage": True}
            headers = {**get_cli_headers(), "Content-Type": "application/json"}
            if client_wants_stream or use_responses:
                headers["Accept"] = "text/event-stream"
            print(f"[{datetime.now().strftime('%H:%M:%S')}] {'Responses' if use_responses else 'Chat'} -> {model}")
            req = Request(upstream_url, data=json.dumps(data).encode('utf-8'), headers=headers)
            with urlopen(req, timeout=120) as resp:
                self.send_response(resp.status)
                if use_responses:
                    self.send_header('Content-Type', 'text/event-stream')
                    self.send_header('Access-Control-Allow-Origin', '*')
                    self.end_headers()
                    full_response = resp.read().decode('utf-8')
                    tool_calls = []
                    content_text = ""
                    response_id = None
                    created = None
                    for line in full_response.split("\n"):
                        if line.startswith("data: "):
                            try:
                                event_data = json.loads(line[6:])
                                response = event_data.get("response", event_data)
                                if not response_id:
                                    response_id = response.get("id", f"chatcmpl-{uuid.uuid4().hex[:24]}")
                                    created = response.get("created_at", int(datetime.now().timestamp()))
                                for item in response.get("output", []):
                                    if item.get("type") == "function_call":
                                        call_id = item.get("call_id", item.get("id", f"call_{uuid.uuid4().hex[:16]}"))
                                        name = item.get("name", "unknown")
                                        args = item.get("arguments", "{}")
                                        if isinstance(args, dict):
                                            args = json.dumps(args)
                                        existing = next((tc for tc in tool_calls if tc["id"] == call_id), None)
                                        if not existing:
                                            tool_calls.append({"id": call_id, "type": "function", "function": {"name": name, "arguments": args}})
                                    elif item.get("type") == "message" and item.get("role") == "assistant":
                                        for part in item.get("content", []):
                                            if part.get("type") == "output_text":
                                                content_text += part.get("text", "")
                                if event_data.get("response", {}).get("status") == "completed":
                                    delta = {}
                                    if tool_calls:
                                        delta["tool_calls"] = tool_calls
                                    elif content_text:
                                        delta["content"] = content_text
                                    chunk = {
                                        "id": response_id,
                                        "object": "chat.completion.chunk",
                                        "created": created,
                                        "model": model,
                                        "choices": [{"index": 0, "delta": delta, "finish_reason": "tool_calls" if tool_calls else "stop"}]
                                    }
                                    self.wfile.write(f"data: {json.dumps(chunk)}\n\n".encode())
                                    self.wfile.flush()
                            except:
                                pass
                else:
                    self.send_header('Content-Type', resp.headers.get('Content-Type', 'text/event-stream'))
                    self.send_header('Access-Control-Allow-Origin', '*')
                    self.end_headers()
                    while True:
                        chunk = resp.read(4096)
                        if not chunk:
                            break
                        self.wfile.write(chunk)
                        self.wfile.flush()
        except HTTPError as e:
            error_body = e.read() if e.fp else b''
            self.send_response(e.code)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Access-Control-Allow-Origin', '*')
            self.end_headers()
            self.wfile.write(error_body or json.dumps({"error": str(e)}).encode())
        except Exception as e:
            self.send_error(500, str(e).encode())

def kill_old_process():
    """Убивает предыдущий процесс прокси (Termux-совместимый способ)"""
    import os
    import signal
    import subprocess
    import time
    current_pid = os.getpid()
    # 1. Пробуем убить по PID-файлу
    pid_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "zen-free-proxy.pid")
    if os.path.exists(pid_file):
        try:
            with open(pid_file) as f:
                old_pid = int(f.read().strip())
            if old_pid != current_pid:
                os.kill(old_pid, signal.SIGKILL)
                print(f"[*] Убит старый процесс PID {old_pid} (по PID-файлу)")
        except (ValueError, ProcessLookupError, PermissionError, OSError):
            pass
    # 2. Пробуем pgrep + kill (исключая текущий PID)
    try:
        result = subprocess.run(['pgrep', '-f', 'zen-free-proxy.py'], capture_output=True, text=True, timeout=5)
        if result.stdout.strip():
            for pid_line in result.stdout.strip().split('\n'):
                try:
                    pid = int(pid_line.strip())
                    if pid != current_pid:
                        os.kill(pid, signal.SIGKILL)
                        print(f"[*] Убит старый процесс PID {pid} (по pgrep)")
                except (ValueError, ProcessLookupError, PermissionError, OSError):
                    pass
    except (FileNotFoundError, Exception):
        pass
    # 3. Ждём освобождения порта
    import socket
    for _ in range(10):
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(1)
            sock.bind(('127.0.0.1', LISTEN_PORT))
            sock.close()
            return
        except OSError:
            time.sleep(1)

def run_server():
    import os
    kill_old_process()
    HTTPServer.allow_reuse_address = True
    server = HTTPServer(('127.0.0.1', LISTEN_PORT), ZenProxyHandler)
    # Сохраняем PID
    pid_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "zen-free-proxy.pid")
    try:
        with open(pid_file, 'w') as f:
            f.write(str(os.getpid()))
    except OSError:
        pass
    print(f"[*] Zen Free Proxy v19 запущен на http://127.0.0.1:{LISTEN_PORT}")
    print(f"[*] Session: {SESSION_ID}")
    print(f"[*] Content conversion: ВКЛЮЧЕНА")
    server.serve_forever()

if __name__ == '__main__':
    run_server()

